// types of the virtual modules generated by plugins/mdx-pages.ts
declare module 'virtual:mdx-pages' {
    import type { ComponentType } from 'react'

    // Components usable from the MDX files, e.g. `<Highlight>`
    export type MdxComponents = Record<string, ComponentType<never>>

    export interface MdxPageProps {
        components?: MdxComponents
    }

    export interface MdxPageEntry {
        slug: string
        title: string
        load: () => Promise<{ default: ComponentType<MdxPageProps> }>
    }

    // every file of mdx-pages/ (non-recursively), ordered by `export const index`
    export const pages: readonly MdxPageEntry[]
}

declare module 'virtual:mdx-posts' {
    import type { ComponentType } from 'react'
    import type { MdxPageProps } from 'virtual:mdx-pages'

    export interface MdxPostEntry {
        slug: string
        fileName: string
        load: () => Promise<{ default: ComponentType<MdxPageProps>; metadata?: unknown }>
    }

    // every file of mdx-pages/posts/
    export const posts: readonly MdxPostEntry[]
}

declare module 'virtual:mdx-search' {
    export interface MdxSearchDocument {
        kind: 'page' | 'post'
        slug: string
        text: string
    }

    // posts, pages
    export const documents: readonly MdxSearchDocument[]
}
